import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"服務條款","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/terms.md","filePath":"zh-TW/guide/terms.md","lastUpdated":1793173149000}`),a={name:`zh-TW/guide/terms.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="服務條款" tabindex="-1">服務條款 <a class="header-anchor" href="#服務條款" aria-label="Permalink to “服務條款”">​</a></h1><p>本條款規範你對 Sudoku 應用程式的使用。下載、安裝或使用 Sudoku，即表示你同意本條款。若你不同意，請勿使用本應用程式。</p><h2 id="授權與使用" tabindex="-1">授權與使用 <a class="header-anchor" href="#授權與使用" aria-label="Permalink to “授權與使用”">​</a></h2><p>Sudoku 依各版本隨附的授權條款提供。我們授予你有限、非專屬、不可轉讓的授權，讓你在自己的裝置上依授權條款使用本應用程式。</p><h2 id="離線優先設計與選用的雲端功能" tabindex="-1">離線優先設計與選用的雲端功能 <a class="header-anchor" href="#離線優先設計與選用的雲端功能" aria-label="Permalink to “離線優先設計與選用的雲端功能”">​</a></h2><p>Sudoku 是一款以離線優先為設計原則的應用程式。所有遊戲資料——設定、遊戲狀態與統計資料——預設都儲存在你的裝置本機。</p><p>選用的雲端功能包括：</p><ul><li><strong>iCloud 同步</strong>（透過 CloudKit）：使用你的個人 iCloud 帳號，在 Apple 裝置間同步資料。</li><li><strong>Game Center</strong>：提供排行榜與成就。</li><li><strong>「更多 App」</strong>：選用功能，用於取得相關 App 的清單；不會傳送任何個人資料。</li></ul><p>除你明確選擇使用時由 Apple 的 iCloud 與 Game Center 服務所管理的資料外，我們不會蒐集任何個人資料。</p><h2 id="使用者責任" tabindex="-1">使用者責任 <a class="header-anchor" href="#使用者責任" aria-label="Permalink to “使用者責任”">​</a></h2><ul><li>以合法方式使用 Sudoku，並遵守相關規範。</li><li>不得以違反授權的方式嘗試反編譯、逆向工程或修改本 App。</li><li>不得將本 App 用於任何不法用途。</li></ul><h2 id="隱私" tabindex="-1">隱私 <a class="header-anchor" href="#隱私" aria-label="Permalink to “隱私”">​</a></h2><p>請參閱隱私權政策以瞭解資料處理方式。簡而言之：我們不蒐集任何資料；選用的雲端功能僅在你明確同意的情況下，使用 Apple 的 iCloud 與 Game Center 服務。</p><h2 id="免責聲明" tabindex="-1">免責聲明 <a class="header-anchor" href="#免責聲明" aria-label="Permalink to “免責聲明”">​</a></h2><p>Sudoku 按「現狀」提供，不附任何形式的保證。在法律允許的最大範圍內，維護人員否認一切明示、默示、法定或其他保證，包括可商業性與特定用途適用性之保證。</p><h2 id="責任限制" tabindex="-1">責任限制 <a class="header-anchor" href="#責任限制" aria-label="Permalink to “責任限制”">​</a></h2><p>在法律允許的最大範圍內，維護人員對於因你使用本應用程式而產生的任何間接、附隨、特殊、衍生或懲罰性損害，概不負責。</p><h2 id="終止" tabindex="-1">終止 <a class="header-anchor" href="#終止" aria-label="Permalink to “終止”">​</a></h2><p>若你未遵守本條款，授予你的權利將自動終止。</p><h2 id="條款變更" tabindex="-1">條款變更 <a class="header-anchor" href="#條款變更" aria-label="Permalink to “條款變更”">​</a></h2><p>我們可能不時更新本條款。條款變更後繼續使用，即視為接受修訂後的條款。</p><h2 id="聯絡我們" tabindex="-1">聯絡我們 <a class="header-anchor" href="#聯絡我們" aria-label="Permalink to “聯絡我們”">​</a></h2><p>若對本條款有任何疑問，請在專案儲存庫提出 issue：<code>https://github.com/sudoku-pro/sudoku-site/issues</code>。</p><p><em>最後更新：2026-07-29</em></p>`,24)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};